#include "codegen.h"
#include <stdexcept>
void CodeGenerator::emitExpression(const ASTNode&n){if(n.nodeType=="Number"||n.nodeType=="String"||n.nodeType=="Bool"||n.nodeType=="None"){code.push_back({n.nodeType=="Number"?"CONST":n.nodeType=="String"?"CONST_STR":n.nodeType=="Bool"?"CONST_BOOL":"CONST_NONE",n.value});return;}if(n.nodeType=="Identifier"){code.push_back({"LOAD",n.value});return;}if(n.nodeType=="Assign"){emitExpression(*n.children[0]);code.push_back({"STORE",n.value});return;}if(n.nodeType=="Unary"){emitExpression(*n.children[0]);code.push_back({n.value=="-"?"NEG":"NOT",""});return;}if(n.nodeType=="Binary"){emitExpression(*n.children[0]);emitExpression(*n.children[1]);const auto&o=n.value;code.push_back({o=="+"?"ADD":o=="-"?"SUB":o=="*"?"MUL":o=="/"?"DIV":o=="%"?"MOD":o=="=="?"EQ":o=="!="?"NE":o=="<"?"LT":o==">"?"GT":o=="<="?"LE":"GE",""});return;}throw std::runtime_error("Unsupported AST node: "+n.nodeType);}
void CodeGenerator::emitStatement(const ASTNode&n){if(n.nodeType=="Print"){emitExpression(*n.children[0]);code.push_back({"PRINT",""});return;}if(n.nodeType=="VarDecl"){if(n.children.empty())code.push_back({"CONST_NONE",""});else emitExpression(*n.children[0]);code.push_back({"STORE",n.value});return;}if(n.nodeType=="If"){emitExpression(*n.children[0]);const auto jf=code.size();code.push_back({"JMP_IF_FALSE","0"});for(const auto&x:n.children[1]->children)emitStatement(*x);if(n.children.size()>2){const auto j=code.size();code.push_back({"JMP","0"});code[jf].arg=std::to_string(code.size());for(const auto&x:n.children[2]->children)emitStatement(*x);code[j].arg=std::to_string(code.size());}else code[jf].arg=std::to_string(code.size());return;}if(n.nodeType=="While"){const auto start=code.size();emitExpression(*n.children[0]);const auto jf=code.size();code.push_back({"JMP_IF_FALSE","0"});for(const auto&x:n.children[1]->children)emitStatement(*x);code.push_back({"JMP",std::to_string(start)});code[jf].arg=std::to_string(code.size());return;}if(n.nodeType=="Block"){for(const auto&x:n.children)emitStatement(*x);return;}emitExpression(n);}
std::vector<Instruction>CodeGenerator::generate(const ASTNode&r){code.clear();for(const auto&n:r.children)emitStatement(*n);code.push_back({"HALT",""});return code;}